import sys

data = sys.stdin.read().split()
q = int(data[0])
reqs = [(int(data[1 + 2 * i]), data[2 + 2 * i]) for i in range(q)]
out = []
for i in range(q):
    t, ip = reqs[i]
    start = None
    count = 0
    for j in range(i):
        tj, ipj = reqs[j]
        if ipj != ip:
            continue
        if start is None or tj >= start + 60:
            start = tj
            count = 1
        elif count < 10:
            count += 1
    if start is None or t >= start + 60 or count < 10:
        out.append('ALLOW')
    else:
        out.append('DENY')
print('\n'.join(out))

